messageHandlers.script:
# Receive toolbar state updates from content views
logger = system.util.getLogger('HeaderToolbar')

states = payload.get('states', {})

if 'new' in states:
	self.view.custom.btnNewEnabled = states['new']
if 'edit' in states:
	self.view.custom.btnEditEnabled = states['edit']
if 'save' in states:
	self.view.custom.btnSaveEnabled = states['save']
if 'cancel' in states:
	self.view.custom.btnCancelEnabled = states['cancel']
if 'delete' in states:
	self.view.custom.btnDeleteEnabled = states['delete']
if 'insertLine' in states:
	self.view.custom.btnInsertLineEnabled = states['insertLine']
if 'deleteLine' in states:
	self.view.custom.btnDeleteLineEnabled = states['deleteLine']
if 'print' in states:
	self.view.custom.btnPrintEnabled = states['print']
if 'find' in states:
	self.view.custom.btnFindEnabled = states['find']
if 'first' in states:
	self.view.custom.btnFirstEnabled = states['first']
if 'previous' in states:
	self.view.custom.btnPreviousEnabled = states['previous']
if 'next' in states:
	self.view.custom.btnNextEnabled = states['next']
if 'last' in states:
	self.view.custom.btnLastEnabled = states['last']

# Build summary of enabled buttons
enabled = [k for k, v in states.items() if v]
disabled = [k for k, v in states.items() if not v]
msg = 'Toolbar updated - Enabled: ' + str(enabled)
logger.info(msg)
system.perspective.sendMessage('debug-log', {'source': 'Toolbar', 'message': msg}, scope='session')
